import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:timezone/data/latest.dart' as timezone_data;
import 'package:timezone/timezone.dart' as timezone;

import 'app/router.dart';
import 'app/theme.dart';
import 'firebase_options.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  timezone_data.initializeTimeZones();
  timezone.setLocalLocation(timezone.getLocation('Asia/Manila'));
  // Firebase configuration is generated by `flutterfire configure`.
  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
  } catch (_) {
    // Keep the foundation launchable until Firebase configuration is supplied.
  }
  runApp(const ProviderScope(child: BipswayApp()));
}

class BipswayApp extends StatelessWidget {
  const BipswayApp({super.key});

  @override
  Widget build(BuildContext context) => MaterialApp.router(
        title: 'Bipsway',
        theme: AppTheme.light,
        darkTheme: AppTheme.dark,
        themeMode: ThemeMode.light,
        routerConfig: appRouter,
      );
}
